#define ESC_CN_UI_PAIR_COUNT (int)(sizeof(esc_cn_ui_pairs) / sizeof(esc_cn_ui_pairs[0]))

int escalayer_reboot_cn_ui_pair_count(void)
{
	return ESC_CN_UI_PAIR_COUNT;
}

const char *escalayer_reboot_cn_ui_sjis(int i)
{
	if (i < 0 || i >= ESC_CN_UI_PAIR_COUNT)
		return NULL;
	return esc_cn_ui_pairs[i].sjis;
}

const char *escalayer_reboot_cn_ui_gbk(int i)
{
	if (i < 0 || i >= ESC_CN_UI_PAIR_COUNT)
		return NULL;
	return esc_cn_ui_pairs[i].gbk;
}

static struct string *esc_make_cow_string(const char *text)
{
	struct string *s = cstr_to_string(text);
	s->cow = true;
	return s;
}

int escalayer_reboot_replace_cn_ui_text(struct string **strings, int nr_strings)
{
	int replaced = 0;

	if (!strings || nr_strings <= 0)
		return 0;

	for (int i = 0; i < nr_strings; i++) {
		if (!strings[i])
			continue;
		for (int p = 0; p < ESC_CN_UI_PAIR_COUNT; p++) {
			if (strcmp(strings[i]->text, esc_cn_ui_pairs[p].sjis) != 0)
				continue;
			struct string *neu = esc_make_cow_string(esc_cn_ui_pairs[p].gbk);
			free_string(strings[i]);
			strings[i] = neu;
			replaced++;
			break;
		}
	}
	return replaced;
}
